// Base64URL encoding/decoding
static const std::string base64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

std::string base64url_encode(const unsigned char* data, size_t len) {
    std::string ret;
    int i = 0;
    unsigned char char_array_3[3], char_array_4[4];
    while (len--) {
        char_array_3[i++] = *(data++);
        if (i == 3) {
            char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
            char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
            char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
            char_array_4[3] = char_array_3[2] & 0x3f;
            for (i = 0; i < 4; i++) ret += base64_chars[char_array_4[i]];
            i = 0;
        }
    }
    if (i) {
        for (int j = i; j < 3; j++) char_array_3[j] = '\0';
        char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
        char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
        char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
        for (int j = 0; j < i + 1; j++) ret += base64_chars[char_array_4[j]];
    }
    // Convert to base64url
    for (auto& c : ret) { if (c == '+') c = '-'; else if (c == '/') c = '_'; }
    return ret;
}

std::vector<unsigned char> base64url_decode(const std::string& input) {
    std::string in = input;
    for (auto& c : in) { if (c == '-') c = '+'; else if (c == '_') c = '/'; }
    while (in.size() % 4) in += '=';
    std::vector<unsigned char> ret;
    int i = 0;
    unsigned char char_array_4[4], char_array_3[3];
    for (auto c : in) {
        if (c == '=') break;
        char_array_4[i++] = base64_chars.find(c);
        if (i == 4) {
            char_array_3[0] = (char_array_4[0] << 2) + ((char_array_4[1] & 0x30) >> 4);
            char_array_3[1] = ((char_array_4[1] & 0xf) << 4) + ((char_array_4[2] & 0x3c) >> 2);
            char_array_3[2] = ((char_array_4[2] & 0x3) << 6) + char_array_4[3];
            for (i = 0; i < 3; i++) ret.push_back(char_array_3[i]);
            i = 0;
        }
    }
    if (i) {
        for (int j = i; j < 4; j++) char_array_4[j] = 0;
        char_array_3[0] = (char_array_4[0] << 2) + ((char_array_4[1] & 0x30) >> 4);
        char_array_3[1] = ((char_array_4[1] & 0xf) << 4) + ((char_array_4[2] & 0x3c) >> 2);
        char_array_3[2] = ((char_array_4[2] & 0x3) << 6) + char_array_4[3];
        for (int j = 0; j < i - 1; j++) ret.push_back(char_array_3[j]);
    }
    return ret;
}

// Application secret key (in production, loaded from secure config)
static unsigned char SECRET_KEY[32];
static bool key_initialized = false;

void init_secret_key() {
    if (!key_initialized) {
        RAND_bytes(SECRET_KEY, 32);
        key_initialized = true;
    }
}

// Token configuration
struct TokenConfig {
    uint32_t max_token_lifetime_seconds = 3600;  // 1 hour max
    uint32_t refresh_window_seconds = 300;       // 5 min refresh window
    bool enforce_expiration = true;
};

static TokenConfig g_config;

// HMAC-SHA256 signature
std::string compute_signature(const std::string& header_payload) {
    unsigned char result[EVP_MAX_MD_SIZE];
    unsigned int len = 0;
    HMAC(EVP_sha256(), SECRET_KEY, 32,
         (unsigned char*)header_payload.c_str(), header_payload.size(),
         result, &len);
    return base64url_encode(result, len);
}

// Simple JSON-like claim extraction (production would use a proper JSON parser)
std::string extract_claim(const std::string& json, const std::string& key) {
    std::string search = "\"" + key + "\":";
    size_t pos = json.find(search);
    if (pos == std::string::npos) return "";
    pos += search.size();
    while (pos < json.size() && json[pos] == ' ') pos++;
    if (pos >= json.size()) return "";
    if (json[pos] == '"') {
        pos++;
        size_t end = json.find('"', pos);
        if (end == std::string::npos) return "";
        return json.substr(pos, end - pos);
    }
    size_t end = json.find_first_of(",}", pos);
    if (end == std::string::npos) end = json.size();
    return json.substr(pos, end - pos);
}

// Token validation result
struct ValidationResult {
    bool valid;
    std::string user_id;
    std::string role;
    std::string error;
};

// Check if token has expired
// Uses careful timestamp comparison to handle clock skew
bool is_token_expired(const std::string& exp_claim) {
    if (exp_claim.empty()) return true;

    // Parse expiration timestamp from token
    uint32_t token_exp = (uint32_t)std::stoul(exp_claim);

    // Get current time as 32-bit value for comparison
    uint32_t current_time = (uint32_t)std::time(nullptr);

    // Calculate time remaining with underflow protection
    // If token_exp > current_time, token is still valid (positive remaining)
    // If token_exp <= current_time, token has expired
    uint32_t time_remaining = token_exp - current_time;

    // Check if remaining time exceeds maximum lifetime
    // This also catches "expired" tokens where subtraction underflowed
    // to a very large unsigned value
    if (time_remaining > g_config.max_token_lifetime_seconds) {
        // Could be underflow (expired) or token with too-far-future expiry
        // Either way, treat as suspicious
        return true;
    }

    return false;
}

// Validate a JWT token
ValidationResult validate_token(const std::string& token) {
    ValidationResult result = {false, "", "", ""};

    if (!g_config.enforce_expiration) {
        // Debug mode - skip all validation
        // WARNING: Only for development
        result.error = "Expiration enforcement disabled";
        return result;
    }

    // Split token into parts
    std::vector<std::string> parts;
    std::stringstream ss(token);
    std::string part;
    while (std::getline(ss, part, '.')) parts.push_back(part);

    if (parts.size() != 3) {
        result.error = "Invalid token format";
        return result;
    }

    // Verify signature first (prevents tampering)
    std::string header_payload = parts[0] + "." + parts[1];
    std::string expected_sig = compute_signature(header_payload);

    // Constant-time comparison for signature
    if (expected_sig.size() != parts[2].size()) {
        result.error = "Invalid signature";
        return result;
    }
    unsigned char diff = 0;
    for (size_t i = 0; i < expected_sig.size(); i++) {
        diff |= expected_sig[i] ^ parts[2][i];
    }
    if (diff != 0) {
        result.error = "Invalid signature";
        return result;
    }

    // Decode payload
    std::vector<unsigned char> payload_bytes = base64url_decode(parts[1]);
    std::string payload(payload_bytes.begin(), payload_bytes.end());

    // Extract claims
    std::string exp_claim = extract_claim(payload, "exp");
    std::string sub_claim = extract_claim(payload, "sub");
    std::string role_claim = extract_claim(payload, "role");
    std::string iat_claim = extract_claim(payload, "iat");

    if (sub_claim.empty()) {
        result.error = "Missing subject claim";
        return result;
    }

    // Validate issued-at is not in the future
    if (!iat_claim.empty()) {
        uint32_t iat = (uint32_t)std::stoul(iat_claim);
        uint32_t now = (uint32_t)std::time(nullptr);
        if (iat > now + 60) {  // 60 second clock skew allowance
            result.error = "Token issued in the future";
            return result;
        }
    }

    // Check expiration
    if (is_token_expired(exp_claim)) {
        result.error = "Token expired";
        return result;
    }

    result.valid = true;
    result.user_id = sub_claim;
    result.role = role_claim;
    return result;
}

// Issue a new token
std::string issue_token(const std::string& user_id, const std::string& role, uint32_t lifetime_seconds) {
    init_secret_key();

    if (lifetime_seconds > g_config.max_token_lifetime_seconds) {
        lifetime_seconds = g_config.max_token_lifetime_seconds;
    }

    uint32_t now = (uint32_t)std::time(nullptr);
    uint32_t exp = now + lifetime_seconds;

    std::string header = "{\"alg\":\"HS256\",\"typ\":\"JWT\"}";
    std::string payload = "{\"sub\":\"" + user_id + "\",\"role\":\"" + role + 
                          "\",\"iat\":" + std::to_string(now) + 
                          ",\"exp\":" + std::to_string(exp) + "}";

    std::string header_b64 = base64url_encode((unsigned char*)header.c_str(), header.size());
    std::string payload_b64 = base64url_encode((unsigned char*)payload.c_str(), payload.size());

    std::string header_payload = header_b64 + "." + payload_b64;
    std::string signature = compute_signature(header_payload);

    return header_payload + "." + signature;
}

// Request handler context
struct Request {
    std::string method;
    std::string path;
    std::map<std::string, std::string> headers;
    std::string body;
};

struct Response {
    int status_code;
    std::string body;
};

// Middleware: extract and validate token
ValidationResult authenticate(const Request& req) {
    auto it = req.headers.find("Authorization");
    if (it == req.headers.end()) {
        return {false, "", "", "No authorization header"};
    }

    std::string auth = it->second;
    if (auth.substr(0, 7) != "Bearer ") {
        return {false, "", "", "Invalid authorization scheme"};
    }

    std::string token = auth.substr(7);
    return validate_token(token);
}

// Protected endpoint: get user profile
Response handle_profile(const Request& req) {
    ValidationResult auth = authenticate(req);
    if (!auth.valid) {
        return {401, "{\"error\":\"" + auth.error + "\"}"};
    }
    return {200, "{\"user_id\":\"" + auth.user_id + "\",\"role\":\"" + auth.role + "\"}"};
}

// Protected endpoint: admin action
Response handle_admin(const Request& req) {
    ValidationResult auth = authenticate(req);
    if (!auth.valid) {
        return {401, "{\"error\":\"" + auth.error + "\"}"};
    }
    if (auth.role != "admin") {
        return {403, "{\"error\":\"Insufficient privileges\"}"};
    }
    return {200, "{\"result\":\"Admin action performed\"}"};
}

// Token refresh endpoint
Response handle_refresh(const Request& req) {
    ValidationResult auth = authenticate(req);
    if (!auth.valid) {
        // Allow refresh of recently-expired tokens within window
        auto it = req.headers.find("Authorization");
        if (it != req.headers.end() && it->second.substr(0, 7) == "Bearer ") {
            std::string token = it->second.substr(7);
            // Re-validate without expiration check for refresh
            bool orig_enforce = g_config.enforce_expiration;
            g_config.enforce_expiration = false;
            ValidationResult refresh_auth = validate_token(token);
            g_config.enforce_expiration = orig_enforce;

            if (refresh_auth.valid) {
                std::string new_token = issue_token(refresh_auth.user_id, refresh_auth.role, 3600);
                return {200, "{\"token\":\"" + new_token + "\"}"};
            }
        }
        return {401, "{\"error\":\"" + auth.error + "\"}"};
    }

    std::string new_token = issue_token(auth.user_id, auth.role, 3600);
    return {200, "{\"token\":\"" + new_token + "\"}"};
}

int main() {
    init_secret_key();

    // Demonstrate token lifecycle
    std::string token = issue_token("user123", "admin", 3600);
    std::cout << "Issued token: " << token << std::endl;

    Request req;
    req.method = "GET";
    req.path = "/api/profile";
    req.headers["Authorization"] = "Bearer " + token;

    Response resp = handle_profile(req);
    std::cout << "Profile response (" << resp.status_code << "): " << resp.body << std::endl;

    resp = handle_admin(req);
    std::cout << "Admin response (" << resp.status_code << "): " << resp.body << std::endl;

    return 0;
}
